import{_ as o}from"./eye-bd28630a.js";import{_ as l,X as r,n as d,p as c,q as u,t,y as a,H as i,a9 as p,w as h}from"./framework-0e2f11f3.js";const g={};function m(f,e){const n=r("SecureChainEcosystemSelector"),s=r("WhatsNext");return d(),c("div",null,[u(" markdownlint-disable MD029 MD024 MD036 "),e[1]||(e[1]=t("h1",{id:"securechain-for-open-source-software",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#securechain-for-open-source-software","aria-hidden":"true",tabindex:"-1"},"#"),a(" SecureChain for Open Source Software")],-1)),i(n),e[2]||(e[2]=p('<h2 id="what-securechain-covers" tabindex="-1"><a class="header-anchor" href="#what-securechain-covers" aria-hidden="true" tabindex="-1">#</a> What SecureChain Covers</h2><ul><li>Verified, signed builds from trusted sources</li><li>Coverage that continues after upstream end of life</li><li>A single registry your developers and CI already know how to talk to</li></ul><h2 id="vulnerability-coverage-and-target-response-times" tabindex="-1"><a class="header-anchor" href="#vulnerability-coverage-and-target-response-times" aria-hidden="true" tabindex="-1">#</a> Vulnerability Coverage and Target Response Times</h2><p>TuxCare employs the Common Vulnerability Scoring System (CVSS) to assess the severity of security vulnerabilities. TuxCare&#39;s severity rating system for patching vulnerabilities integrates both NVD scoring and vendor scoring (when available). When the vendor&#39;s score is lower than the NVD score, the NVD score takes priority.</p><p>Aligning with many industry standards and regulatory requirements, TuxCare delivers timely security updates. For instance, the Payment Card Industry Data Security Standard (PCI DSS) requires organizations to address all &#39;High&#39; vulnerabilities (CVSS score of 7.0+) within 30 days. Other regulations and standards, such as the Health Insurance Portability and Accountability Act (HIPAA) for healthcare or the Federal Information Security Management Act (FISMA) for government agencies, uphold similar requirements.</p><ul><li><p><strong>Vulnerability coverage.</strong> TuxCare provides security patches for critical (CVSS 9.0+), high (CVSS 7.0–8.9), medium (CVSS 4.0–6.9), and low (CVSS below 4.0) vulnerabilities. TuxCare reserves the right to offer a mitigation strategy as an alternative to a direct code fix.</p></li><li><p><strong>Response time.</strong> Target response times depend on where a package sits in its lifecycle — whether upstream is still releasing fixes, or TuxCare is maintaining the package after upstream activity has stopped. TuxCare will make commercially reasonable efforts to adhere to the following guidelines:</p></li></ul><table><thead><tr><th style="text-align:left;">Severity</th><th style="text-align:center;">Maintenance <em>(from upstream fix)</em></th><th style="text-align:center;">Sustained <em>(from CVE publication)</em></th><th style="text-align:center;">Endless Lifecycle Support <em>(from CVE publication)</em></th></tr></thead><tbody><tr><td style="text-align:left;">Critical (CVSS 9.0+)</td><td style="text-align:center;">7 days</td><td style="text-align:center;">14 days</td><td style="text-align:center;">14 days</td></tr><tr><td style="text-align:left;">High (CVSS 7.0–8.9)</td><td style="text-align:center;">14 days</td><td style="text-align:center;">21 days</td><td style="text-align:center;">14 days</td></tr><tr><td style="text-align:left;">Medium (CVSS 4.0–6.9)</td><td style="text-align:center;">30 days</td><td style="text-align:center;">60 days</td><td style="text-align:center;">60 days</td></tr><tr><td style="text-align:left;">Low (CVSS below 4.0)</td><td style="text-align:center;">60 days</td><td style="text-align:center;">90 days</td><td style="text-align:center;">90 days</td></tr></tbody></table><p>These cycles reflect the stages of a package&#39;s support lifecycle:</p><ul><li><strong>Maintenance</strong> — upstream is actively releasing fixes (an upstream release within the last 180 days). Response times start from the upstream fix.</li><li><strong>Sustained</strong> — once there have been 90 days with no upstream release, TuxCare maintains the package directly. Response times start from CVE publication.</li><li><strong>Endless Lifecycle Support (ELS)</strong> — from day 181 of no upstream release onward, TuxCare provides continued patching under ELS. Response times start from CVE publication.</li></ul><h2 id="incident-reporting-and-response-timeframe" tabindex="-1"><a class="header-anchor" href="#incident-reporting-and-response-timeframe" aria-hidden="true" tabindex="-1">#</a> Incident Reporting and Response Timeframe</h2><p>Customers can report vulnerabilities by submitting a ticket through the <a href="https://tuxcare.com/support-portal/" target="_blank" rel="noopener noreferrer">TuxCare Support Portal</a>. TuxCare commits to providing an initial response to any reported issue within 3 days.</p><p>TuxCare reviews requests for customer-directed security patches for CVEs that are outside of the SecureChain scope within 3 working days. If TuxCare accepts the request, it provides the patch within the next 60 days.</p><p>Handling Multiple Vulnerabilities: When customers report several CVEs for fixing at the same time, TuxCare will discuss and agree upon resolution timelines separately with the customer.</p><h2 id="enhanced-transparency-visibility" tabindex="-1"><a class="header-anchor" href="#enhanced-transparency-visibility" aria-hidden="true" tabindex="-1">#</a> Enhanced Transparency &amp; Visibility</h2><p>TuxCare&#39;s commitment to transparency and visibility is foundational to the SecureChain offering. TuxCare provides verifiable metadata that helps customers understand package composition, software provenance, and vulnerability impact across the software supply chain.</p><ul><li><strong>SLSA Compliance</strong>: TuxCare packages are built and signed to support verifiable Supply-chain Levels for Software Artifacts (SLSA) compliance at Level 3. Builds run from vetted sources, include attestations for dependencies, and undergo continuous testing to maintain integrity and trust.</li><li><strong>Software Bill of Materials (SBOM)</strong>: Machine-readable SBOMs provide visibility into package composition and dependencies, supporting software supply chain transparency and accountability. Depending on the package, TuxCare provides SBOMs in industry-standard formats — SPDX and CycloneDX.</li></ul><div class="warning custom-block"><p class="custom-block-title"></p><p>Note: SBOM availability varies by package. Customers can ask about a specific package through the <a href="https://tuxcare.com/support-portal/" target="_blank" rel="noopener noreferrer">TuxCare Support Portal</a>; if you are evaluating TuxCare, contact <a href="mailto:sales@tuxcare.com">sales@tuxcare.com</a>.</p></div><ul><li><strong>Vulnerability Exploitability eXchange (VEX)</strong>: Machine-readable VEX documents provide contextual vulnerability information, helping teams understand which known CVEs affect specific package versions and reduce remediation noise. TuxCare publishes VEX in standard formats, including CycloneDX VEX.</li><li><strong>Verifiable Integrity and Provenance</strong>: Packages and metadata provide end-to-end provenance information, helping customers verify the build, test, and distribution history of the software.</li><li><strong>Secure Distribution</strong>: TuxCare-managed infrastructure distributes signed packages and associated metadata, ensuring authenticity and integrity.</li></ul><h2 id="support-duration" tabindex="-1"><a class="header-anchor" href="#support-duration" aria-hidden="true" tabindex="-1">#</a> Support Duration</h2><p>TuxCare provides continuous security patching for all SecureChain-supported open-source packages for as long as your organization requires them, eliminating the need for rushed or disruptive upgrades.</p><p>TuxCare delivers all updates at a fixed price for the full term of your contract, ensuring predictable costs and uninterrupted protection.</p><h2 id="technical-support" tabindex="-1"><a class="header-anchor" href="#technical-support" aria-hidden="true" tabindex="-1">#</a> Technical Support</h2><p>TuxCare provides technical support according to the standard <a href="https://tuxcare.com/TuxCare-support-policy.pdf" target="_blank" rel="noopener noreferrer">support policy</a>.</p><p>It delivers 24/7/365 access to TuxCare&#39;s support team through the <a href="https://tuxcare.com/support-portal/" target="_blank" rel="noopener noreferrer">TuxCare Support Portal</a> and to TuxCare&#39;s online knowledge base.</p>',24)),i(s,{"hide-title":""},{default:h(()=>e[0]||(e[0]=[t("ul",null,[t("li",null,[t("img",{src:o,alt:""}),a(),t("a",{href:"https://tuxcare.com/cve-tracker/",target:"_blank",rel:"noopener noreferrer"},"CVE Tracker"),a(" — Track vulnerability fixes and updates")])],-1)])),_:1,__:[0]})])}const b=l(g,[["render",m],["__file","index.html.vue"]]);export{b as default};
